def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not points:
        return [row[:] for row in grid]

    # The marked lines encode a periodic color field. Identify the line
    # coordinate that is constant along each monochromatic clue line.
    key_funcs = [
        ("row", lambda r, c: r),
        ("column", lambda r, c: c),
        ("anti_diagonal", lambda r, c: r + c),
        ("diagonal", lambda r, c: r - c),
    ]
    candidates = []
    for name, key in key_funcs:
        by_key = {}
        valid = True
        for r, c, color in points:
            k = key(r, c)
            if k in by_key and by_key[k] != color:
                valid = False
                break
            by_key[k] = color
        if valid:
            candidates.append((len(by_key), name, key, by_key))
    if not candidates:
        raise ValueError("nonzero clues do not form monochromatic parallel lines")
    # Prefer the valid coordinate with the greatest number of clue lines.
    _, _, key, known = max(candidates, key=lambda x: x[0])

    # Find the smallest fully represented residue cycle consistent with all
    # marked lines, then extend that cycle over the whole grid.
    keys = list(known)
    period = None
    residue_color = None
    for p in range(1, max(h, w) + 1):
        mapping = {}
        for k, color in known.items():
            residue = k % p
            if residue in mapping and mapping[residue] != color:
                break
            mapping[residue] = color
        else:
            if len(mapping) == p:
                period, residue_color = p, mapping
                break
    if period is None:
        raise ValueError("could not infer a complete period from clue lines")
    return [[residue_color[key(r, c) % period] for c in range(w)] for r in range(h)]

